export { check, hash, sha }

export const PROJECT_REF = "icockcoguyadhryzydvl"
export const SOURCE_PROFILE = "neuvetra.private-synthetic-staging.v1"
export const SNAPSHOT_PROFILE = "neuvetra.m80.foundation-application-snapshot.v1"
export const BACKUP_PROFILE = "neuvetra.m80.foundation-hosted-backup-receipt.v1"
export const RESTORE_PROFILE = "neuvetra.m80.foundation-hosted-restore-receipt.v1"
export const PRESERVATION_PROFILE = "neuvetra.m80.foundation-hosted-preservation-receipt.v1"
export const REHEARSAL_PROFILE = "neuvetra.m80.foundation-hosted-migration-rehearsal-receipt.v1"
export const MIGRATION_NAME = "0022_scope1_beta_foundation.sql"
export const MIGRATION_SHA256 = "0ee148b366e803e8cf28187393f9e5a6f19b29f5bb54578e359db7cbcd795e35"
export const FIXTURE_SHA256 = "2c6a9f78cded2a209bf536969e4ea389baa7fe1633c8ef63fad0c22826f77dc1"
export const EXPECTED_NEW_TABLES = [
  "scope1_beta_audit",
  "scope1_beta_fixture_admissions",
  "scope1_beta_release_records",
  "scope1_beta_requests",
  "scope1_beta_setup_heads",
  "scope1_beta_setup_versions",
] as const
export const EXPECTED_NEW_TABLE_ROW_COUNTS = {
  scope1_beta_audit: 0,
  scope1_beta_fixture_admissions: 0,
  scope1_beta_release_records: 4,
  scope1_beta_requests: 0,
  scope1_beta_setup_heads: 0,
