  "neuvetra.m80_assert_setup(target_company uuid, s jsonb)",
  "neuvetra.save_scope1_beta_setup(target_company uuid, request jsonb, setup jsonb, version_payload jsonb)",
] as const
export const EXPECTED_NEW_SEQUENCES = ["scope1_beta_audit_sequence_seq"] as const
export const PROVIDER_EXCLUSION = "Application-only archive. Referenced synthetic Auth UUID stubs and auth.uid() definition are retained solely for foreign-key and RLS reconstruction. Provider Auth accounts, credentials, sessions, configuration, storage, platform schemas and provider-wide recovery are excluded."

type MigrationReceipt = { name: string; sha256: string }
type TableSecurity = { name: string; owner: string; rowSecurity: boolean; forceRowSecurity: boolean; acl: string }
type SchemaSecurity = { name: string; owner: string; acl: string }
type InternalTrigger = { tableName: string; constraintTable: string; constraintName: string; enabled: string }

export interface ApplicationState {
  inventory: Inventory
  migrationReceipts: MigrationReceipt[]
  observedNonReceiptTables: string[]
  tableSecurity: TableSecurity[]
  schemaSecurity: SchemaSecurity[]
  internalTriggers: InternalTrigger[]
  contentSha256: string
  metadataSha256: string
  applicationStateSha256: string
}

export interface AuthDependencies {
  authUserIds: string[]
  authUidDefinition: string
  runtimeActorId: string
  providerRecoveryExcluded: true
}

export interface M80ApplicationSnapshot {
  profile: typeof SNAPSHOT_PROFILE
  completedAt: string
  projectRef: typeof PROJECT_REF
  sourceSchemaVersion: 21
  applicationOnly: true
  syntheticDataOnly: true
  providerRecoveryExcluded: true
  providerExclusion: typeof PROVIDER_EXCLUSION
  sourceDatabase: string
  sourceApplicationStateSha256: string
  state: ApplicationState
  authDependencies: AuthDependencies
  customDumpSha256: string
  customDumpBase64: string
}

