  expectedNewTableRowCounts: typeof EXPECTED_NEW_TABLE_ROW_COUNTS
  forcedRlsVerified: true
  runtimeSelectOnlyVerified: true
  runtimeDirectWritesDenied: true
  operatorAdmissionNotExecuted: true
  allConnectionsClosed: true
  hostedEvidence: false
}

export interface DumpTransport {
  dump(database: string, snapshotId: string): Promise<Uint8Array>
}

const TABLE_SECURITY_SQL = `select 'neuvetra.'||c.relname name,pg_get_userbyid(c.relowner) owner,c.relrowsecurity "rowSecurity",c.relforcerowsecurity "forceRowSecurity",coalesce(c.relacl::text,acldefault('r',c.relowner)::text) acl from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra'and c.relkind='r'order by c.relname`
const SCHEMA_SECURITY_SQL = `select n.nspname name,pg_get_userbyid(n.nspowner) owner,coalesce(n.nspacl::text,acldefault('n',n.nspowner)::text) acl from pg_namespace n where n.nspname='neuvetra'`
const INTERNAL_TRIGGER_SQL = `select tn.nspname||'.'||tc.relname "tableName",t.tgname "triggerName",kn.nspname||'.'||kc.relname "constraintTable",k.conname "constraintName",pg_get_triggerdef(t.oid) definition,t.tgenabled::text enabled from pg_trigger t join pg_class tc on tc.oid=t.tgrelid join pg_namespace tn on tn.oid=tc.relnamespace join pg_constraint k on k.oid=t.tgconstraint join pg_class kc on kc.oid=k.conrelid join pg_namespace kn on kn.oid=kc.relnamespace where tn.nspname='neuvetra'and t.tgisinternal order by 1,2`

export function exactKeys(value: unknown, keys: readonly string[], message: string): asserts value is Record<string, unknown> {
  check(!!value && typeof value === "object" && !Array.isArray(value) && Object.getPrototypeOf(value) === Object.prototype, message)
  check(Object.keys(value as Record<string, unknown>).sort().join("|") === [...keys].sort().join("|"), message)
}

export function validateDisposableDatabaseName(name: string): void {
  check(/^m80_(ops|qa|backup)_foundation_[0-9]{10,}$/.test(name) && name.length <= 63, "Fresh M80 disposable database required.")
}

export async function exactMigrationManifest21(): Promise<MigrationReceipt[]> {
  const manifest = await readMigrationManifest()
  check(manifest.length >= 22 && manifest[21]?.name === MIGRATION_NAME && manifest[21]?.sha256 === MIGRATION_SHA256, "Frozen schema 22 migration changed.")
  check(sha(await readFile(`packages/neuvetra-database/src/migrations/${MIGRATION_NAME}`)) === MIGRATION_SHA256, "Migration 22 bytes changed.")
  return manifest.slice(0, 21).map(({ name, sha256 }) => ({ name, sha256 }))
}

function contentProjection(state: Pick<ApplicationState, "inventory" | "migrationReceipts">) {
  return {
    tables: state.inventory.tables.filter(table => table.name !== "schema_migrations").map(table => ({ name: table.name, count: table.count, rowHashes: table.rowHashes })),
    migrationReceipts: state.migrationReceipts,
  }
}

function metadataProjection(state: Omit<ApplicationState, "contentSha256" | "metadataSha256" | "applicationStateSha256">) {
  const { inventory: value } = state
  return {
    nonReceiptTables: state.observedNonReceiptTables,
    tableSecurity: state.tableSecurity,
    schemaSecurity: state.schemaSecurity,
    internalTriggers: state.internalTriggers,
    functions: value.functions,
    tableObjects: value.tableObjects,
    sequences: value.sequences,
    roles: value.roles,
    memberships: value.memberships,
    defaultAcls: value.defaultAcls,
    dependencies: value.dependencies,
  }
}

export async function captureApplicationState(tx: WorkspaceSql): Promise<ApplicationState> {
  const value = await inventory(tx)
  const migrationReceipts = (await tx.query<MigrationReceipt>("select name,sha256 from neuvetra.schema_migrations order by name")).rows
  const observedNonReceiptTables = value.tables.filter(table => table.name !== "schema_migrations").map(table => `neuvetra.${table.name}`)
  check(observedNonReceiptTables.length > 0 && observedNonReceiptTables.every((name, index, all) => /^neuvetra\.[a-z][a-z0-9_]*$/.test(name) && (index === 0 || all[index - 1]! < name)), "Derived table names must be unique and sorted.")
  const tableSecurity = (await tx.query<TableSecurity>(TABLE_SECURITY_SQL)).rows
  const schemaSecurity = (await tx.query<SchemaSecurity>(SCHEMA_SECURITY_SQL)).rows
  const internalTriggers = (await tx.query<InternalTrigger & { triggerName: string; definition: string }>(INTERNAL_TRIGGER_SQL)).rows.map(({ triggerName: _triggerName, definition: _definition, ...semantic }) => semantic)
  const raw = { inventory: value, migrationReceipts, observedNonReceiptTables, tableSecurity, schemaSecurity, internalTriggers }
  const contentSha256 = hash(contentProjection(raw))
  const metadataSha256 = hash(metadataProjection(raw))
  return { ...raw, contentSha256, metadataSha256, applicationStateSha256: hash({ contentSha256, metadataSha256 }) }
}

export async function verifyExactSource21(tx: WorkspaceSql, expectedDatabase: string, expectedMode: "local" | "hosted"): Promise<void> {
  const target = (await tx.query<{ database: string; actor: string; address: string | null; port: number | null; readOnly: string }>("select current_database() database,current_user actor,host(inet_server_addr()) address,inet_server_port() port,current_setting('transaction_read_only') \"readOnly\"")).rows[0]
  check(target?.database === expectedDatabase && target.readOnly === "on", "Exact read-only source database required.")
  if (expectedMode === "local") check(target.actor === "supabase_admin" && target.port === 55472 && ["127.0.0.1", "::1"].includes(target.address ?? ""), "Exact local source target required.")
  else check(target.actor === "postgres" && target.database === "postgres", "Exact hosted source target required.")
  const expected = await exactMigrationManifest21()
  const actual = (await tx.query<MigrationReceipt>("select name,sha256 from neuvetra.schema_migrations order by name")).rows
  check(canonical(actual) === canonical(expected), "Exact schema 21 migration receipts required.")
  const profile = (await tx.query<{ projectRef: string; profile: string }>("select project_ref \"projectRef\",profile from neuvetra.staging_target")).rows
  check(profile.length === 1 && profile[0]!.projectRef === PROJECT_REF && profile[0]!.profile === SOURCE_PROFILE, "Exact synthetic staging target required.")
}

async function captureAuthDependencies(tx: WorkspaceSql): Promise<AuthDependencies> {
  const refs = (await tx.query<{ tableName: string; columnName: string }>("select c.relname \"tableName\",a.attname \"columnName\" from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum=k.conkey[1] where n.nspname='neuvetra'and k.contype='f'and k.confrelid='auth.users'::regclass and cardinality(k.conkey)=1 order by 1,2")).rows
  check(refs.length > 0 && refs.every(row => /^[a-z][a-z0-9_]*$/.test(row.tableName) && /^[a-z][a-z0-9_]*$/.test(row.columnName)), "Only scalar Auth UUID dependencies are supported.")
  const union = refs.map(row => `select ${row.columnName} id from neuvetra.${row.tableName}`).join(" union all ")
  const authUserIds = (await tx.query<{ id: string }>(`select distinct id::text id from (${union})u where id is not null order by id`)).rows.map(row => row.id)
  check(authUserIds.length > 0 && authUserIds.every(id => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(id)), "Referenced Auth UUIDs required.")
  const authUidDefinition = (await tx.query<{ definition: string }>("select pg_get_functiondef('auth.uid()'::regprocedure) definition")).rows[0]?.definition
  check(typeof authUidDefinition === "string" && authUidDefinition.includes("auth.uid"), "auth.uid definition required.")
  const runtimeActorId = (await tx.query<{ id: string }>("select user_id::text id from neuvetra.staging_access where active order by user_id limit 1")).rows[0]?.id
  check(!!runtimeActorId && authUserIds.includes(runtimeActorId), "Referenced synthetic runtime actor required.")
  return { authUserIds, authUidDefinition, runtimeActorId, providerRecoveryExcluded: true }
}

export async function createApplicationSnapshot(db: WorkspaceConnection, expectedDatabase: string, mode: "local" | "hosted", dumpTransport: DumpTransport): Promise<M80ApplicationSnapshot> {
  return db.transaction(async tx => {
    await tx.exec("set transaction isolation level repeatable read read only")
    await verifyExactSource21(tx, expectedDatabase, mode)
    const snapshotId = (await tx.query<{ snapshot: string }>("select pg_export_snapshot() snapshot")).rows[0]!.snapshot
    const state = await captureApplicationState(tx)
    check(state.migrationReceipts.length === 21 && state.observedNonReceiptTables.length === state.inventory.tables.length - 1, "Derived schema 21 inventory required.")
    const authDependencies = await captureAuthDependencies(tx)
    const dump = await dumpTransport.dump(expectedDatabase, snapshotId)
    check(dump.byteLength > 16, "Complete custom dump required.")
    const after = await captureApplicationState(tx)
    check(hash(state) === hash(after), "Source changed during snapshot dump.")
    return {
      profile: SNAPSHOT_PROFILE,
      completedAt: new Date().toISOString(),
      projectRef: PROJECT_REF,
      sourceSchemaVersion: 21,
      applicationOnly: true,
      syntheticDataOnly: true,
      providerRecoveryExcluded: true,
      providerExclusion: PROVIDER_EXCLUSION,
      sourceDatabase: expectedDatabase,
      sourceApplicationStateSha256: state.applicationStateSha256,
      state,
      authDependencies,
      customDumpSha256: sha(dump),
      customDumpBase64: Buffer.from(dump).toString("base64"),
    }
  })
}

export function validateApplicationSnapshot(value: unknown, expectedSnapshotSha256: string): M80ApplicationSnapshot {
  check(typeof value === "object" && value !== null && !Array.isArray(value), "Snapshot object required.")
  const snapshot = value as M80ApplicationSnapshot
  check(digest(expectedSnapshotSha256) && sha(JSON.stringify(snapshot)) === expectedSnapshotSha256, "Snapshot bytes changed.")
  check(snapshot.profile === SNAPSHOT_PROFILE && snapshot.projectRef === PROJECT_REF && snapshot.sourceSchemaVersion === 21 && snapshot.applicationOnly === true && snapshot.syntheticDataOnly === true && snapshot.providerRecoveryExcluded === true && snapshot.providerExclusion === PROVIDER_EXCLUSION, "Snapshot boundary changed.")
  check(snapshot.state.migrationReceipts.length === 21 && snapshot.state.applicationStateSha256 === hash({ contentSha256: snapshot.state.contentSha256, metadataSha256: snapshot.state.metadataSha256 }), "Snapshot state binding changed.")
  check(snapshot.state.contentSha256 === hash(contentProjection(snapshot.state)) && snapshot.state.metadataSha256 === hash(metadataProjection(snapshot.state)), "Snapshot inventory hash changed.")
  check(snapshot.authDependencies.providerRecoveryExcluded === true && snapshot.authDependencies.authUserIds.includes(snapshot.authDependencies.runtimeActorId), "Snapshot Auth dependency boundary changed.")
  const dump = Buffer.from(snapshot.customDumpBase64, "base64")
  check(dump.byteLength > 16 && sha(dump) === snapshot.customDumpSha256, "Custom dump changed.")
  return snapshot
}

export function assertExactRestore(source: ApplicationState, restored: ApplicationState): void {
  sameExactInventory(source.inventory, restored.inventory)
  check(hash(source) === hash(restored), "Restored application state differs.")
}

function exactOldMetadata(source: ApplicationState, after: ApplicationState): void {
  const oldTables = new Set(source.inventory.tables.map(table => table.name))
  const oldFunctions = new Set(source.inventory.functions.map(value => value.signature))
  const oldSequences = new Set(source.inventory.sequences.map(value => value.name))
  check(hash(source.tableSecurity) === hash(after.tableSecurity.filter(row => oldTables.has(row.name.replace("neuvetra.", "")))), "Old table ACL or RLS metadata changed.")
  check(hash(source.schemaSecurity) === hash(after.schemaSecurity), "Schema ACL changed.")
  check(hash(source.inventory.functions) === hash(after.inventory.functions.filter(value => oldFunctions.has(value.signature))), "Old function metadata changed.")
  check(hash(source.inventory.tableObjects) === hash(after.inventory.tableObjects.filter(value => oldTables.has(value.table_name))), "Old object metadata changed.")
  check(hash(source.inventory.sequences) === hash(after.inventory.sequences.filter(value => oldSequences.has(value.name))), "Old sequence metadata changed.")
  for (const key of ["roles", "memberships", "defaultAcls", "dependencies"] as const) check(hash(source.inventory[key]) === hash(after.inventory[key]), `Old ${key} changed.`)
  for (const trigger of source.internalTriggers) check(after.internalTriggers.some(value => hash(value) === hash(trigger)), "Old internal trigger changed.")
  const sourceTriggers = new Set(source.internalTriggers.map(value => hash(value)))
  const added = after.internalTriggers.filter(value => !sourceTriggers.has(hash(value)))
  check(added.every(value => (EXPECTED_NEW_TABLES as readonly string[]).includes(value.constraintTable.replace("neuvetra.", ""))), "Unexpected internal trigger added to old objects.")
}

export async function assertSchema22Delta(source: ApplicationState, after: ApplicationState, tx: WorkspaceSql): Promise<void> {
  const sourceTables = new Set(source.inventory.tables.map(table => table.name))
  const addedTables = after.inventory.tables.map(table => table.name).filter(name => !sourceTables.has(name))
  check(canonical(addedTables) === canonical(EXPECTED_NEW_TABLES), "Unexpected schema 22 table delta.")
  for (const old of source.inventory.tables) {
    const current = after.inventory.tables.find(table => table.name === old.name)
    check(!!current, "Old table missing after migration.")
    if (old.name === "schema_migrations") {
      check(current.count === old.count + 1 && old.rowHashes.every(row => current.rowHashes.includes(row)), "Old migration receipts changed.")
    } else check(hash(old) === hash(current), "Old table content changed.")
  }
  for (const [name, count] of Object.entries(EXPECTED_NEW_TABLE_ROW_COUNTS)) check(after.inventory.tables.find(table => table.name === name)?.count === count, "New table row count changed.")
  const expectedReceipts = [...source.migrationReceipts, { name: MIGRATION_NAME, sha256: MIGRATION_SHA256 }]
  check(canonical(after.migrationReceipts) === canonical(expectedReceipts), "Migration 22 receipt changed.")
  exactOldMetadata(source, after)
  const oldFunctions = new Set(source.inventory.functions.map(value => value.signature))
  const addedFunctions = after.inventory.functions.map(value => value.signature).filter(value => !oldFunctions.has(value))
  check(canonical(addedFunctions) === canonical(EXPECTED_NEW_FUNCTIONS), "Unexpected function delta.")
  const oldSequences = new Set(source.inventory.sequences.map(value => value.name))
  const addedSequences = after.inventory.sequences.map(value => value.name).filter(value => !oldSequences.has(value))
  check(canonical(addedSequences) === canonical(EXPECTED_NEW_SEQUENCES), "Unexpected sequence delta.")
  const held = (await tx.query<any>("select profile_id \"profileId\",status,method_id \"methodId\",method_version \"methodVersion\",method_sha256 \"methodSha256\",engine_sha256 \"engineSha256\",factor_identity_sha256 \"factorIdentitySha256\",gwp_identity_sha256 \"gwpIdentitySha256\",source_artifact_ids \"sourceArtifactIds\",reporting_period_start::text \"reportingPeriodStart\",reporting_period_end_exclusive::text \"reportingPeriodEndExclusive\",effective_at \"effectiveAt\",superseded_at \"supersededAt\",exclusions,decision_artifact_sha256 \"decisionArtifactSha256\" from neuvetra.scope1_beta_release_records order by profile_id")).rows
  const expectedHeld = M80_HELD_REGISTRY.map(row => ({ ...row, reportingPeriodStart: "2025-01-01", reportingPeriodEndExclusive: "2026-01-01", effectiveAt: null, supersededAt: null, exclusions: ["domain_release_pending", "rights_release_pending", "runtime_release_prohibited"], decisionArtifactSha256: "848883159be48c88a0dab8589ad371dcdbbf8dd07966a3d5fbcfd0799f7a530b" })).sort((a, b) => a.profileId.localeCompare(b.profileId))
  check(canonical(held) === canonical(expectedHeld), "Held release seed rows changed.")
  const security = after.tableSecurity.filter(row => (EXPECTED_NEW_TABLES as readonly string[]).includes(row.name.replace("neuvetra.", "")))
  check(security.length === EXPECTED_NEW_TABLES.length && security.every(row => row.rowSecurity && row.forceRowSecurity), "Forced RLS missing on new tables.")
}

export async function applySchema22(tx: WorkspaceSql, source: ApplicationState): Promise<ApplicationState> {
  const current = await captureApplicationState(tx)
  assertExactRestore(source, current)
  const sql = await readFile(`packages/neuvetra-database/src/migrations/${MIGRATION_NAME}`, "utf8")
  check(sha(sql) === MIGRATION_SHA256, "Migration 22 bytes changed.")
  await tx.exec(sql)
  await tx.query("insert into neuvetra.schema_migrations(name,sha256) values($1,$2)", [MIGRATION_NAME, MIGRATION_SHA256])
  const after = await captureApplicationState(tx)
  await assertSchema22Delta(source, after, tx)
  return after
}

export function createBackupReceipt(snapshot: M80ApplicationSnapshot, snapshotSha256: string, encryptedArchiveSha256: string): BackupReceipt {
  check(digest(snapshotSha256) && digest(encryptedArchiveSha256), "Backup hashes required.")
  return { profile: BACKUP_PROFILE, completedAt: new Date().toISOString(), projectRef: PROJECT_REF, sourceSchemaVersion: 21, sourceApplicationStateSha256: snapshot.sourceApplicationStateSha256, applicationOnly: true, syntheticDataOnly: true, providerRecoveryExcluded: true, encryptedArchiveSha256, snapshotSha256, customDumpSha256: snapshot.customDumpSha256 }
}

