function cleanPgEnvironment(database: string) {
  return {
    ...Object.fromEntries(Object.entries(process.env).filter(([key]) => !key.toUpperCase().startsWith("PG"))),
    PGHOST: "127.0.0.1",
    PGPORT: "55472",
    PGDATABASE: database,
    PGUSER: "supabase_admin",
    PGSSLMODE: "disable",
    PGCONNECT_TIMEOUT: "10",
  }
}

async function child(command: string[], stdin?: Uint8Array | string, environment?: Record<string, string | undefined>): Promise<Uint8Array> {
  const process = Bun.spawn(command, { env: environment, stdin: stdin === undefined ? "ignore" : "pipe", stdout: "pipe", stderr: "pipe" })
  if (stdin !== undefined) {
    await process.stdin.write(stdin)
    await process.stdin.end()
  }
  const [stdout, , code] = await Promise.all([new Response(process.stdout).arrayBuffer(), new Response(process.stderr).text(), process.exited])
  check(code === 0, "Private child process failed.")
  return new Uint8Array(stdout)
}

async function assertOwnedOutput(path: string, root: string): Promise<string> {
  const full = resolve(path)
  const allowed = await realpath(root)
  check(dirname(full) === allowed && basename(full).startsWith("m80-backup-"), "Exclusive M80 backup path required.")
  check(!relative(allowed, full).startsWith("..") && !relative(allowed, full).includes(":"), "Backup path escaped its private root.")
  check(!await Bun.file(full).exists(), "Existing backup output refused.")
  return full
}

async function writeExclusive(path: string, value: unknown): Promise<{ sha256: string; bytes: Uint8Array }> {
  const bytes = new TextEncoder().encode(JSON.stringify(value, null, 2) + "\n")
  const file = await open(path, "wx", 0o600)
  try { await file.writeFile(bytes); await file.sync() } finally { await file.close() }
  return { sha256: sha(bytes), bytes }
}

async function appendJournal(file: Awaited<ReturnType<typeof open>>, value: unknown): Promise<void> {
  await file.writeFile(JSON.stringify(value) + "\n")
  await file.sync()
}

async function sealSnapshot(snapshotText: string, archivePath: string): Promise<void> {
  const output = await child(["powershell.exe", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", SEAL_SCRIPT, "-Mode", "Seal", "-ArchivePath", archivePath], snapshotText)
  check(JSON.parse(new TextDecoder().decode(output)).status === "m80_backup_archive_sealed", "Archive seal receipt changed.")
}

async function unsealSnapshot(archivePath: string): Promise<string> {
  return new TextDecoder().decode(await child(["powershell.exe", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", SEAL_SCRIPT, "-Mode", "Unseal", "-ArchivePath", archivePath]))
}

async function restoreSnapshot(snapshot: M80ApplicationSnapshot, snapshotSha256: string, database: string): Promise<Awaited<ReturnType<typeof captureApplicationState>>> {
  validateDisposableDatabaseName(database)
  const admin = createPostgresConnection("postgres://supabase_admin@127.0.0.1:55472/postgres", { tls: false, maxConnections: 1 })
  let restored: ReturnType<typeof createPostgresConnection> | undefined
  try {
    check((await admin.query("select 1 from pg_database where datname=$1", [database])).rows.length === 0, "Occupied restore target refused.")
    await admin.exec(`create database ${database} template template0`)
    restored = createPostgresConnection(`postgres://supabase_admin@127.0.0.1:55472/${database}`, { tls: false, maxConnections: 1 })
    await restored.exec("revoke all on schema public from public,anon,authenticated; create schema auth; create table auth.users(id uuid primary key); grant usage on schema auth to postgres,authenticated,neuvetra_runtime")
    for (const id of snapshot.authDependencies.authUserIds) await restored.query("insert into auth.users(id) values($1)", [id])
    await restored.exec(snapshot.authDependencies.authUidDefinition)
    const dump = Buffer.from(validateApplicationSnapshot(snapshot, snapshotSha256).customDumpBase64, "base64")
    await child([resolve(PG_ROOT, "pg_restore.exe"), "--exit-on-error", "--single-transaction", "--no-password", `--dbname=${database}`], dump, cleanPgEnvironment(database))
    return await restored.transaction(async tx => {
      await tx.exec("set transaction isolation level repeatable read read only")
      await verifyExactSource21(tx, database, "local")
      return captureApplicationState(tx)
    })
  } finally {
    await restored?.close()
    await admin.close()
  }
}

async function verifyRuntimeBoundary(database: string, actorId: string): Promise<{ selectOnly: true; directWritesDenied: true; admissionNotExecuted: true }> {
  const operator = createPostgresConnection(`postgres://supabase_admin@127.0.0.1:55472/${database}`, { tls: false, maxConnections: 1 })
  const runtime = createPostgresConnection(`postgres://neuvetra_runtime@127.0.0.1:55472/${database}`, { tls: false, maxConnections: 1 })
  try {
    const releaseCount = await runtime.transaction(async tx => {
      await tx.query("select set_config('request.jwt.claim.sub',$1,true)", [actorId])
      return (await tx.query<{ count: number }>("select count(*)::int count from neuvetra.scope1_beta_release_records")).rows[0]!.count
    })
    check(releaseCount === 4, "Runtime held registry read failed.")
    let denied = false
    try {
      await runtime.transaction(async tx => {
        await tx.query("select set_config('request.jwt.claim.sub',$1,true)", [actorId])
        await tx.exec("delete from neuvetra.scope1_beta_release_records where false")
      })
    } catch { denied = true }
    check(denied, "Runtime direct write unexpectedly succeeded.")
    const admissions = (await operator.query<{ count: number }>("select count(*)::int count from neuvetra.scope1_beta_fixture_admissions")).rows[0]!.count
    check(admissions === 0, "Operator admission was executed during rehearsal.")
    return { selectOnly: true, directWritesDenied: true, admissionNotExecuted: true }
  } finally {
    await runtime.close()
    await operator.close()
  }
}

export async function runLocalRehearsal(): Promise<{ outputDirectory: string; database: string; receiptHashes: Record<string, string> }> {
  const suffix = Date.now().toString()
  const database = `m80_backup_foundation_${suffix}`
  validateDisposableDatabaseName(database)
  const privateRoot = resolve(`.superpowers/m80-backup-rehearsal-${suffix}`)
  await mkdir(privateRoot)
  const paths = {
    archive: await assertOwnedOutput(`${privateRoot}/m80-backup-application.dpapi`, privateRoot),
    backup: await assertOwnedOutput(`${privateRoot}/m80-backup-receipt.json`, privateRoot),
    restore: await assertOwnedOutput(`${privateRoot}/m80-backup-restore-receipt.json`, privateRoot),
    preservation: await assertOwnedOutput(`${privateRoot}/m80-backup-preservation-receipt.json`, privateRoot),
    migration: await assertOwnedOutput(`${privateRoot}/m80-backup-migration-rehearsal-receipt.json`, privateRoot),
    journal: await assertOwnedOutput(`${privateRoot}/m80-backup-journal.jsonl`, privateRoot),
    result: await assertOwnedOutput(`${privateRoot}/m80-backup-result.json`, privateRoot),
  }
  const journal = await open(paths.journal, "wx", 0o600)
  let source: ReturnType<typeof createPostgresConnection> | undefined
  let clone: ReturnType<typeof createPostgresConnection> | undefined
  let stage = "source_snapshot"
  try {
    await appendJournal(journal, { status: "m80_backup_rehearsal_started", completedAt: new Date().toISOString(), sourceSchemaVersion: 21, database, hostedEvidence: false })
    source = createPostgresConnection(`postgres://supabase_admin@127.0.0.1:55472/${SOURCE_DATABASE}`, { tls: false, maxConnections: 1 })
    const snapshot = await createApplicationSnapshot(source, SOURCE_DATABASE, "local", {
      dump: async (sourceDatabase, snapshotId) => child([resolve(PG_ROOT, "pg_dump.exe"), "--format=custom", "--no-password", "--schema=neuvetra", `--snapshot=${snapshotId}`], undefined, cleanPgEnvironment(sourceDatabase)),
    })
    const snapshotText = JSON.stringify(snapshot)
    const snapshotSha256 = sha(snapshotText)
    stage = "encrypted_archive"
    await sealSnapshot(snapshotText, paths.archive)
    const encryptedArchiveSha256 = sha(new Uint8Array(await Bun.file(paths.archive).arrayBuffer()))
    const backupReceipt: BackupReceipt = createBackupReceipt(snapshot, snapshotSha256, encryptedArchiveSha256)
    const backupWrite = await writeExclusive(paths.backup, backupReceipt)
    await appendJournal(journal, { status: "m80_backup_encrypted", completedAt: backupReceipt.completedAt, encryptedArchiveSha256, snapshotSha256, customDumpSha256: snapshot.customDumpSha256 })
    const roundTripText = await unsealSnapshot(paths.archive)
    check(sha(roundTripText) === snapshotSha256, "Encrypted snapshot round trip changed.")
    const roundTrip = validateApplicationSnapshot(JSON.parse(roundTripText), snapshotSha256)
    const tampered = structuredClone(roundTrip)
    tampered.customDumpSha256 = "0".repeat(64)
    let tamperRejected = false
    try { validateApplicationSnapshot(tampered, sha(JSON.stringify(tampered))) } catch { tamperRejected = true }
    check(tamperRejected, "Tampered snapshot admitted.")
    stage = "fresh_local_restore"
    const restored = await restoreSnapshot(roundTrip, snapshotSha256, database)
    assertExactRestore(snapshot.state, await restored)
    const restoreReceipt: RestoreReceipt = { profile: RESTORE_PROFILE, completedAt: new Date().toISOString(), disposableDatabaseName: database, sourceBackupReceiptSha256: backupWrite.sha256, sourceSchemaVersion: 21, observedNonReceiptTables: restored.observedNonReceiptTables, observedNonReceiptTableCount: restored.observedNonReceiptTables.length, oldMigrationReceiptCount: 21, allConnectionsClosed: true }
    const preservationReceipt: PreservationReceipt = { profile: PRESERVATION_PROFILE, completedAt: new Date().toISOString(), disposableDatabaseName: database, observedNonReceiptTableCount: restored.observedNonReceiptTables.length, observedNonReceiptTablesSha256: hash(restored.observedNonReceiptTables), historicalReferenceNonReceiptTableCount: 120, oldMigrationReceiptCount: 21, sourceContentSha256: snapshot.state.contentSha256, restoredContentSha256: restored.contentSha256, sourceMetadataSha256: snapshot.state.metadataSha256, restoredMetadataSha256: restored.metadataSha256, oldContentExact: true, oldMetadataExact: true }
    stage = "schema22_rehearsal"
    clone = createPostgresConnection(`postgres://supabase_admin@127.0.0.1:55472/${database}`, { tls: false, maxConnections: 1 })
    await clone.transaction(tx => applySchema22(tx, snapshot.state))
    await clone.close(); clone = undefined
    const runtime = await verifyRuntimeBoundary(database, snapshot.authDependencies.runtimeActorId)
    await source.close(); source = undefined
    const sourceFinal = createPostgresConnection(`postgres://supabase_admin@127.0.0.1:55472/${SOURCE_DATABASE}`, { tls: false, maxConnections: 1 })
    try {
      const finalState = await sourceFinal.transaction(async tx => { await tx.exec("set transaction isolation level repeatable read read only"); await verifyExactSource21(tx, SOURCE_DATABASE, "local"); return captureApplicationState(tx) })
      assertExactRestore(snapshot.state, await finalState)
    } finally { await sourceFinal.close() }
    const migrationReceipt: MigrationRehearsalReceipt = { profile: REHEARSAL_PROFILE, completedAt: new Date().toISOString(), disposableDatabaseName: database, sourceSchemaVersion: 21, targetSchemaVersion: 22, migrationSha256: MIGRATION_SHA256, expectedNewTables: EXPECTED_NEW_TABLES, expectedNewTableRowCounts: EXPECTED_NEW_TABLE_ROW_COUNTS, forcedRlsVerified: true, runtimeSelectOnlyVerified: runtime.selectOnly, runtimeDirectWritesDenied: runtime.directWritesDenied, operatorAdmissionNotExecuted: runtime.admissionNotExecuted, allConnectionsClosed: true, hostedEvidence: false }
    const restoreWrite = await writeExclusive(paths.restore, restoreReceipt)
    const preservationWrite = await writeExclusive(paths.preservation, preservationReceipt)
    const migrationWrite = await writeExclusive(paths.migration, migrationReceipt)
    const receiptHashes = { backup: backupWrite.sha256, restore: restoreWrite.sha256, preservation: preservationWrite.sha256, migration: migrationWrite.sha256 }
    const result = { profile: "neuvetra.m80.foundation-local-backup-rehearsal-result.v1", completedAt: new Date().toISOString(), sourceSchemaVersion: 21, targetSchemaVersion: 22, disposableDatabaseName: database, observedNonReceiptTableCount: restored.observedNonReceiptTables.length, encryptedArchiveSha256, snapshotSha256, customDumpSha256: snapshot.customDumpSha256, sourceApplicationStateSha256: snapshot.sourceApplicationStateSha256, receiptHashes, sourceDatabaseUnchanged: true, snapshotTamperRejected: true, archiveExclusiveAndDurable: true, providerRecoveryExcluded: true, hostedEvidence: false }
    await writeExclusive(paths.result, result)
    await appendJournal(journal, { status: "m80_backup_rehearsal_completed", completedAt: result.completedAt, database, receiptHashes })
    return { outputDirectory: privateRoot, database, receiptHashes }
  } catch (error) {
    try { await appendJournal(journal, { status: "m80_backup_rehearsal_failed_do_not_retry_silently", completedAt: new Date().toISOString(), stage, database, freshCloneMayBeRetained: ["fresh_local_restore", "schema22_rehearsal"].includes(stage) }) } catch {}
    throw new Error(`M80 backup rehearsal failed at ${stage}; inspect the exclusive private journal before any new attempt.`, { cause: error })
  } finally {
    await clone?.close()
    await source?.close()
    await journal.close()
  }
}

if (import.meta.main) {
  try {
    check(process.argv.length === 3 && process.argv[2] === "--execute-local-rehearsal", "Explicit local rehearsal flag required.")
    console.log(JSON.stringify({ status: "m80_backup_local_rehearsal_passed", ...await runLocalRehearsal() }))
  } catch (error) {
    console.error(JSON.stringify({ status: "m80_backup_local_rehearsal_refused_or_failed", message: error instanceof Error ? error.message : "Unknown failure." }))
    process.exitCode = 1
  }
}

/** Fixed root-only hosted schema-21 inspection/backup entrypoint. Importing performs no I/O. */
import { open, readFile, realpath } from "node:fs/promises"
import { basename, dirname, relative, resolve } from "node:path"
import { connectOperator, operatorUrl } from "../tools/staging/m73-common"
import {
  PROJECT_REF,
  MIGRATION_SHA256,
  createApplicationSnapshot,
  createBackupReceipt,
  captureApplicationState,
  check,
  exactKeys,
  hash,
  sha,
  verifyExactSource21,
} from "./m80-backup-core"

export const INSPECTION_PROFILE = "neuvetra.m80.foundation-backup-source-inspection.v1" as const
export const ADMISSION_PROFILE = "neuvetra.m80.foundation-backup-admission.v1" as const
export const RUNTIME_CANDIDATE_SHA256 = "40c4ac822ef2d045457ade7dd63d471813178c8f3a585425be58eb81013de59b"
/** Set only after the repaired preparation candidate receives independent acceptance and this helper is re-reviewed. */
export const ACCEPTED_PREPARATION_CANDIDATE_SHA256: string | null = null
const HELPER_PATHS = [
  ".superpowers/m80-backup-core.ts",
  ".superpowers/m80-backup-hosted-entry.ts",
  ".superpowers/m80-backup-private.ps1",
  ".superpowers/m80-backup-seal.ps1",
] as const
const CA_PATH = resolve("tools/cloud/fixtures/supabase-prod-ca-2021.crt")

interface IndependentReview { path: string; sha256: string }
interface BackupAdmission {
  profile: typeof ADMISSION_PROFILE
  observedAt: string
  operatorId: "/root"
  projectRef: typeof PROJECT_REF
  targetClassification: "private_synthetic_staging"
  sourceSchemaVersion: 21
  migrationReceiptCount: 21
  applicationStateSha256: string
  observedNonReceiptTables: string[]
  observedNonReceiptTableCount: number
  syntheticDataOnlyVerified: true
  applicationOnly: true
  providerRecoveryExcluded: true
  candidateSha256: typeof RUNTIME_CANDIDATE_SHA256
  migrationSha256: typeof MIGRATION_SHA256
  preparationCandidateSha256: string
  backupHelperSha256: string
  independentReview: IndependentReview
  rootBackupExecutionAccepted: true
}

function deepContains(value: unknown, expected: string): boolean {
  if (value === expected) return true
  if (Array.isArray(value)) return value.some(item => deepContains(item, expected))
  if (value && typeof value === "object") return Object.values(value as Record<string, unknown>).some(item => deepContains(item, expected))
  return false
}

export async function helperPins() {
  const pins = await Promise.all(HELPER_PATHS.map(async path => ({ path, sha256: sha(await readFile(path)) })))
  return { pins, helperSha256: hash(pins) }
}

async function assertPrivateNewPath(path: string): Promise<string> {
  const full = resolve(path)
  const root = await realpath(resolve(".superpowers"))
  check(dirname(full) === root && basename(full).startsWith("m80-backup-"), "Fixed private M80 output path required.")
  check(!relative(root, full).startsWith("..") && !relative(root, full).includes(":"), "Private output path escaped.")
  check(!await Bun.file(full).exists(), "Existing output refused.")
  return full
}

async function exclusiveJson(path: string, value: unknown): Promise<string> {
  const bytes = new TextEncoder().encode(JSON.stringify(value, null, 2) + "\n")
  const file = await open(await assertPrivateNewPath(path), "wx", 0o600)
  try { await file.writeFile(bytes); await file.sync() } finally { await file.close() }
  return sha(bytes)
}

async function append(file: Awaited<ReturnType<typeof open>>, value: unknown) {
  await file.writeFile(JSON.stringify(value) + "\n")
  await file.sync()
}

function hostedDumpEnvironment(rawUrl: string) {
  const url = operatorUrl(rawUrl)
  return {
    ...Object.fromEntries(Object.entries(process.env).filter(([key]) => !key.toUpperCase().startsWith("PG"))),
    PGHOST: url.hostname,
    PGPORT: url.port,
    PGDATABASE: "postgres",
    PGUSER: decodeURIComponent(url.username),
    PGPASSWORD: decodeURIComponent(url.password),
    PGSSLMODE: "verify-full",
    PGSSLROOTCERT: CA_PATH,
    PGCONNECT_TIMEOUT: "15",
  }
}

async function runChild(command: string[], stdin?: string): Promise<Uint8Array> {
  const child = Bun.spawn(command, { stdin: stdin === undefined ? "ignore" : "pipe", stdout: "pipe", stderr: "pipe" })
  if (stdin !== undefined) { await child.stdin.write(stdin); await child.stdin.end() }
  const [stdout, , code] = await Promise.all([new Response(child.stdout).arrayBuffer(), new Response(child.stderr).text(), child.exited])
  check(code === 0, "Private backup child failed.")
  return new Uint8Array(stdout)
}

async function activeRuntimeSessions(db: Awaited<ReturnType<typeof connectOperator>>): Promise<number> {
  return (await db.query<{ count: number }>("select count(*)::int count from pg_stat_activity where datname=current_database() and usename='neuvetra_runtime' and backend_type='client backend'")).rows[0]!.count
}

export async function inspectHostedSource(rawUrl: string, outputPath: string) {
  operatorUrl(rawUrl)
  const db = await connectOperator(rawUrl)
  try {
    const sourceHelperPins = await helperPins()
    const observation = await db.transaction(async tx => {
      await tx.exec("set transaction isolation level repeatable read read only")
      await verifyExactSource21(tx, "postgres", "hosted")
      const state = await captureApplicationState(tx)
      const count = (await tx.query<{ count: number }>("select count(*)::int count from pg_stat_activity where datname=current_database() and usename='neuvetra_runtime' and backend_type='client backend'")).rows[0]!.count
      check(count === 0, "Active runtime sessions refuse backup inspection.")
      return { state, count }
    })
    const receipt = { profile: INSPECTION_PROFILE, observedAt: new Date().toISOString(), projectRef: PROJECT_REF, sourceSchemaVersion: 21 as const, migrationReceiptCount: 21 as const, applicationStateSha256: observation.state.applicationStateSha256, observedNonReceiptTables: observation.state.observedNonReceiptTables, observedNonReceiptTableCount: observation.state.observedNonReceiptTables.length, activeRuntimeSessionCount: observation.count, noActiveRuntimeSessions: true as const, sourceHelperPins, applicationOnly: true as const, providerRecoveryExcluded: true as const, readOnly: true as const }
    const receiptSha256 = await exclusiveJson(outputPath, receipt)
    return { status: "m80_backup_source_inspection_passed", receiptSha256, observedNonReceiptTableCount: receipt.observedNonReceiptTableCount, applicationStateSha256: receipt.applicationStateSha256 }
  } finally { await db.close() }
}

async function validateAdmission(path: string, expectedSha256: string, currentState: Awaited<ReturnType<typeof captureApplicationState>>): Promise<BackupAdmission> {
  check(ACCEPTED_PREPARATION_CANDIDATE_SHA256 !== null, "No independently accepted preparation candidate is configured.")
  const bytes = await readFile(path)
  check(sha(bytes) === expectedSha256, "Backup admission bytes changed.")
  const value = JSON.parse(bytes.toString("utf8"))
  exactKeys(value, ["profile","observedAt","operatorId","projectRef","targetClassification","sourceSchemaVersion","migrationReceiptCount","applicationStateSha256","observedNonReceiptTables","observedNonReceiptTableCount","syntheticDataOnlyVerified","applicationOnly","providerRecoveryExcluded","candidateSha256","migrationSha256","preparationCandidateSha256","backupHelperSha256","independentReview","rootBackupExecutionAccepted"], "Closed backup admission required.")
  const admission = value as unknown as BackupAdmission
  exactKeys(admission.independentReview, ["path","sha256"], "Closed independent review pin required.")
  const observedAt = Date.parse(admission.observedAt)
  check(Number.isFinite(observedAt) && observedAt <= Date.now() && Date.now() - observedAt <= 4 * 60 * 60 * 1000, "Fresh backup admission required.")
  const helpers = await helperPins()
  check(admission.profile === ADMISSION_PROFILE && admission.operatorId === "/root" && admission.projectRef === PROJECT_REF && admission.targetClassification === "private_synthetic_staging" && admission.sourceSchemaVersion === 21 && admission.migrationReceiptCount === 21 && admission.syntheticDataOnlyVerified === true && admission.applicationOnly === true && admission.providerRecoveryExcluded === true && admission.candidateSha256 === RUNTIME_CANDIDATE_SHA256 && admission.migrationSha256 === MIGRATION_SHA256 && admission.preparationCandidateSha256 === ACCEPTED_PREPARATION_CANDIDATE_SHA256 && admission.backupHelperSha256 === helpers.helperSha256 && admission.rootBackupExecutionAccepted === true, "Backup admission identity changed.")
  check(admission.applicationStateSha256 === currentState.applicationStateSha256 && hash(admission.observedNonReceiptTables) === hash(currentState.observedNonReceiptTables) && admission.observedNonReceiptTableCount === admission.observedNonReceiptTables.length && admission.observedNonReceiptTableCount === currentState.observedNonReceiptTables.length, "Backup admission does not match current schema 21 state.")
  const reviewBytes = await readFile(admission.independentReview.path)
  check(sha(reviewBytes) === admission.independentReview.sha256, "Independent review bytes changed.")
  const review = JSON.parse(reviewBytes.toString("utf8"))
  check(deepContains(review, ACCEPTED_PREPARATION_CANDIDATE_SHA256) && deepContains(review, helpers.helperSha256) && ["pass", "accepted", "accepted_for_backup"].some(verdict => deepContains(review, verdict)), "Independent review does not accept this exact preparation and helper candidate.")
  return admission
}

export async function backupHostedSource(rawUrl: string, admissionPath: string, admissionSha256: string, pgDumpPath: string, archivePath: string, receiptPath: string, journalPath: string) {
  operatorUrl(rawUrl)
  const archive = await assertPrivateNewPath(archivePath)
  const receipt = await assertPrivateNewPath(receiptPath)
  const journalFile = await open(await assertPrivateNewPath(journalPath), "wx", 0o600)
  const db = await connectOperator(rawUrl)
  let stage = "admission"
  try {
    await append(journalFile, { status: "m80_hosted_backup_started", observedAt: new Date().toISOString(), projectRef: PROJECT_REF })
    const state = await db.transaction(async tx => { await tx.exec("set transaction isolation level repeatable read read only"); await verifyExactSource21(tx, "postgres", "hosted"); return captureApplicationState(tx) })
    await validateAdmission(admissionPath, admissionSha256, state)
    check(await activeRuntimeSessions(db) === 0, "Active runtime sessions refuse backup.")
    stage = "snapshot_dump"
    const snapshot = await createApplicationSnapshot(db, "postgres", "hosted", {
      dump: async (_database, snapshotId) => {
        const child = Bun.spawn([resolve(pgDumpPath), "--format=custom", "--no-password", "--schema=neuvetra", `--snapshot=${snapshotId}`], { env: hostedDumpEnvironment(rawUrl), stdout: "pipe", stderr: "pipe" })
        const [dump, , code] = await Promise.all([new Response(child.stdout).arrayBuffer(), new Response(child.stderr).text(), child.exited])
        check(code === 0, "Hosted application dump failed.")
        return new Uint8Array(dump)
      },
    })
    check(snapshot.sourceApplicationStateSha256 === state.applicationStateSha256, "Source changed after backup admission.")
    const snapshotText = JSON.stringify(snapshot)
    const snapshotSha256 = sha(snapshotText)
    stage = "encrypt"
    const sealOutput = await runChild(["powershell.exe", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", resolve(".superpowers/m80-backup-seal.ps1"), "-Mode", "Seal", "-ArchivePath", archive], snapshotText)
    check(JSON.parse(new TextDecoder().decode(sealOutput)).status === "m80_backup_archive_sealed", "Archive seal result changed.")
    const encryptedArchiveSha256 = sha(new Uint8Array(await Bun.file(archive).arrayBuffer()))
    const backupReceipt = createBackupReceipt(snapshot, snapshotSha256, encryptedArchiveSha256)
    const receiptSha256 = await exclusiveJson(receipt, backupReceipt)
    await append(journalFile, { status: "m80_hosted_backup_completed", completedAt: backupReceipt.completedAt, projectRef: PROJECT_REF, encryptedArchiveSha256, snapshotSha256, customDumpSha256: snapshot.customDumpSha256, receiptSha256 })
    return { status: "m80_hosted_backup_completed", receiptSha256, encryptedArchiveSha256, snapshotSha256, customDumpSha256: snapshot.customDumpSha256 }
  } catch {
    try { await append(journalFile, { status: "m80_hosted_backup_failed_do_not_retry_silently", observedAt: new Date().toISOString(), projectRef: PROJECT_REF, stage }) } catch {}
    throw new Error(`M80 hosted backup failed at ${stage}; inspect the exclusive journal before any new attempt.`)
  } finally {
    await db.close()
    await journalFile.close()
  }
}

if (import.meta.main) {
  try {
    const [mode, ...args] = process.argv.slice(2)
    if (mode === "pins") {
      check(args.length === 0, "Pins accepts no arguments.")
      console.log(JSON.stringify(await helperPins()))
    } else if (mode === "inspect") {
      check(args.length === 1, "Inspect requires one new private output path.")
      const input = JSON.parse(await Bun.stdin.text())
      exactKeys(input, ["operatorDatabaseUrl", "operatorId"], "Closed inspect stdin required.")
      check(input.operatorId === "/root" && typeof input.operatorDatabaseUrl === "string", "Root inspect input required.")
      console.log(JSON.stringify(await inspectHostedSource(input.operatorDatabaseUrl, args[0]!)))
    } else if (mode === "backup") {
      check(args.length === 4, "Backup requires pg_dump, archive, receipt and journal paths.")
      const input = JSON.parse(await Bun.stdin.text())
      exactKeys(input, ["operatorDatabaseUrl", "operatorId", "admissionPath", "admissionSha256"], "Closed backup stdin required.")
      check(input.operatorId === "/root" && typeof input.operatorDatabaseUrl === "string" && typeof input.admissionPath === "string" && typeof input.admissionSha256 === "string", "Root backup input required.")
      console.log(JSON.stringify(await backupHostedSource(input.operatorDatabaseUrl, input.admissionPath, input.admissionSha256, args[0]!, args[1]!, args[2]!, args[3]!)))
    } else throw new Error("Explicit pins, inspect or backup mode required.")
  } catch {
    console.error(JSON.stringify({ status: "m80_backup_hosted_entry_refused_or_failed" }))
    process.exitCode = 1
  }
}

param(
  [Parameter(Mandatory=$true)][ValidateSet('Inspect','Backup')][string]$Mode,
  [Parameter(Mandatory=$true)][string]$ExportPath,
  [Parameter(Mandatory=$true)][string]$OutputPath,
  [string]$AdmissionPath,
  [string]$AdmissionSha256,
  [string]$PgDumpPath,
  [string]$ArchivePath,
  [string]$JournalPath
)
$ErrorActionPreference='Stop'
try {
  $values=@()
  foreach($line in [IO.File]::ReadAllLines([IO.Path]::GetFullPath($ExportPath))){
    if($line -match '^\s*(?:export\s+)?DATABASE_URL\s*=\s*(.*?)\s*$'){
      $value=$Matches[1]
      if($value.StartsWith('"')){$value=ConvertFrom-Json $value}
      elseif($value.StartsWith("'") -and $value.EndsWith("'")){$value=$value.Substring(1,$value.Length-2)}
      $values+=$value
    }elseif($line -match '^\s*"DATABASE_URL"\s*:\s*("(?:[^"\\]|\\.)*")\s*,?\s*$'){$values+=(ConvertFrom-Json $Matches[1])}
  }
  if($values.Count -ne 1){throw 'exact DATABASE_URL required'}
  $uri=[Uri]$values[0]
  $user=$uri.UserInfo.Split(':',2)
  if($uri.Scheme -notin @('postgres','postgresql') -or $uri.Host -ne 'aws-1-us-west-1.pooler.supabase.com' -or $uri.Port -ne 5432 -or $uri.AbsolutePath -ne '/postgres' -or [Uri]::UnescapeDataString($user[0]) -ne 'postgres.icockcoguyadhryzydvl' -or $user.Count -ne 2 -or -not $user[1]){throw 'fixed target required'}
  $entry=[IO.Path]::GetFullPath('.superpowers/m80-backup-hosted-entry.ts')
  $start=[Diagnostics.ProcessStartInfo]::new()
  $start.FileName=(Get-Command bun).Source
  $start.UseShellExecute=$false
  $start.CreateNoWindow=$true
  $start.RedirectStandardInput=$true
  $start.RedirectStandardOutput=$true
  $start.RedirectStandardError=$true
  $start.ArgumentList.Add('run');$start.ArgumentList.Add($entry)
  if($Mode -eq 'Inspect'){
    $start.ArgumentList.Add('inspect');$start.ArgumentList.Add([IO.Path]::GetFullPath($OutputPath))
    $input=[ordered]@{operatorDatabaseUrl=$values[0];operatorId='/root'}
  }else{
    if(-not $AdmissionPath -or $AdmissionSha256 -notmatch '^[a-f0-9]{64}$' -or -not $PgDumpPath -or -not $ArchivePath -or -not $JournalPath){throw 'closed backup arguments required'}
    $start.ArgumentList.Add('backup');$start.ArgumentList.Add([IO.Path]::GetFullPath($PgDumpPath));$start.ArgumentList.Add([IO.Path]::GetFullPath($ArchivePath));$start.ArgumentList.Add([IO.Path]::GetFullPath($OutputPath));$start.ArgumentList.Add([IO.Path]::GetFullPath($JournalPath))
    $input=[ordered]@{operatorDatabaseUrl=$values[0];operatorId='/root';admissionPath=[IO.Path]::GetFullPath($AdmissionPath);admissionSha256=$AdmissionSha256}
  }
  $process=[Diagnostics.Process]::Start($start)
  $stdout=$process.StandardOutput.ReadToEndAsync();$stderr=$process.StandardError.ReadToEndAsync()
  $process.StandardInput.Write(($input|ConvertTo-Json -Compress));$process.StandardInput.Close();$process.WaitForExit()
  if($process.ExitCode -ne 0){throw 'private entry refused or failed'}
  [Console]::Out.Write($stdout.Result)
}catch{
  [Console]::Out.Write('{"status":"m80_backup_private_bridge_refused_or_failed","mode":"'+$Mode+'"}')
  exit 1
}

param(
  [ValidateSet('Seal','Unseal')][string]$Mode,
  [Parameter(Mandatory=$true)][string]$ArchivePath
)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Security
$target=[IO.Path]::GetFullPath($ArchivePath)
try {
  if($Mode -eq 'Seal') {
    $plain=[Text.Encoding]::UTF8.GetBytes([Console]::In.ReadToEnd())
    if($plain.Length -lt 1024){throw 'snapshot too small'}
    $protected=[Security.Cryptography.ProtectedData]::Protect($plain,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser)
    $stream=[IO.File]::Open($target,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
    try{$stream.Write($protected,0,$protected.Length);$stream.Flush($true)}finally{$stream.Dispose()}
    $roundTrip=[Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($target),$null,[Security.Cryptography.DataProtectionScope]::CurrentUser)
    $hasher=[Security.Cryptography.SHA256]::Create()
    $plainHash=[Convert]::ToBase64String($hasher.ComputeHash($plain))
    $roundTripHash=[Convert]::ToBase64String($hasher.ComputeHash($roundTrip))
    if($plainHash -ne $roundTripHash){throw 'round trip mismatch'}
    [Console]::Out.Write('{"status":"m80_backup_archive_sealed"}')
  } else {
    $plain=[Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($target),$null,[Security.Cryptography.DataProtectionScope]::CurrentUser)
    [Console]::Out.Write([Text.Encoding]::UTF8.GetString($plain))
  }
} catch {
  [Console]::Error.Write('{"status":"m80_backup_archive_failed","mode":"'+$Mode+'"}')
  exit 1
}
